(r, big) => {
    const calls = big ? 20000 : r.int(2, 30), stations = ["A", "B", "C", "D"].slice(0, big ? 4 : r.int(1, 4));
    const ops = ["TransitLog"], args = [[]];
    const open = new Map(), routes = [];
    let t = 0;
    for (let i = 0; i < calls; i++) {
      t += r.int(0, 3);
      const choice = r.int(0, 2);
      if (choice === 0 || open.size === 0) {
        let id = r.int(1, big ? 1000000 : 6);
        if (open.has(id)) continue;
        const st = r.pick(stations);
        open.set(id, st);
        ops.push("tapIn"); args.push([id, st, t]);
      } else if (choice === 1) {
        const id = r.pick([...open.keys()]), st = r.pick(stations);
        const from = open.get(id);
        open.delete(id);
        t += 1;
        ops.push("tapOut"); args.push([id, st, t]);
        routes.push([from, st]);
      } else if (routes.length) {
        const [a, b] = r.pick(routes);
        ops.push("averageTime"); args.push([a, b]);
      }
    }
    return { ops, args };
  }

