        self.open[id] = (station, t)

    def tapOut(self, id: int, station: str, t: int) -> None:
        start_station, start = self.open.pop(id)
        self.trips.append((start_station, station, t - start))

    def averageTime(self, start: str, end: str) -> float:
        times = [d for a, b, d in self.trips if a == start and b == end]
        return sum(times) / len(times)

