class TransitLog {
  private open = new Map<number, [string, number]>();
  private totals = new Map<string, [number, number]>(); // route -> [sum, count]

  tapIn(id: number, station: string, t: number): void {
    this.open.set(id, [station, t]);
  }

  tapOut(id: number, station: string, t: number): void {
    const [from, start] = this.open.get(id)!;
    this.open.delete(id);
    const key = from + "->" + station; // separator avoids "AB"+"C" vs "A"+"BC" clashes
    const cur = this.totals.get(key) ?? [0, 0];
    this.totals.set(key, [cur[0] + (t - start), cur[1] + 1]);
  }

  averageTime(from: string, to: string): number {
    const [sum, count] = this.totals.get(from + "->" + to)!;
    return sum / count;
  }
}

